class TrySrtTest(unittest.TestCase):
    def setUp(self):
        from hansa import run
        self.tmp = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, self.tmp, ignore_errors=True)
        self.desk = types.SimpleNamespace(state_dir=self.tmp / "state")
        self.srt = str(self.tmp / "srt")
        for patch in (unittest.mock.patch.object(run.shutil, "which", return_value=self.srt),
                      unittest.mock.patch.object(run, "base_env", return_value={"PATH": "/usr/bin:/bin"})):
            patch.start()
            self.addCleanup(patch.stop)

    def test_srt_cannot_start_names_srt_and_its_words_without_the_no_read_hint(self):
        from hansa import run
        results = [subprocess.CompletedProcess([], 2, "", "cannot read Python"),
                   subprocess.CompletedProcess([], 127, "", "env: node: No such file or directory\n")]
        with unittest.mock.patch.object(run.subprocess, "run", side_effect=results), \
                self.assertRaises(run.SrtCannotRun) as failed:
            run.try_srt(self.desk, "settings.json", str(self.tmp), self.tmp)
        self.assertEqual(str(failed.exception),
                         f"srt ({self.srt}) could not start with these sandbox settings: "
                         "env: node: No such file or directory (exit 127)")
        self.assertNotIn("workers may not read", str(failed.exception))
        self.assertFalse(run.srt_record(self.desk)["ran"])

    def test_plain_true_success_keeps_the_relay_message_even_with_startup_words(self):
        from hansa import run
        results = [subprocess.CompletedProcess([], 127, "", "env: node: No such file or directory"),
                   subprocess.CompletedProcess([], 0, "", "")]
        with unittest.mock.patch.object(run.subprocess, "run", side_effect=results), \
                unittest.mock.patch.object(run.sys, "base_prefix", sys.prefix), \
                self.assertRaises(run.SrtCannotRun) as failed:
            run.try_srt(self.desk, "settings.json", str(self.tmp), self.tmp)
        self.assertEqual(str(failed.exception),
                         f"srt ({self.srt}) could not run hansa's output relay and true with these sandbox settings: "
                         "env: node: No such file or directory (exit 127). "
                         "Check whether an entry on 'workers may not read' hides the Python hansa runs with "
                         f"({sys.executable}, prefix {sys.prefix}) or hansa's folder ({Path(run.__file__).resolve().parent}).")
        self.assertFalse(run.srt_record(self.desk)["ran"])
        self.assertIn("exit 127", run.srt_record(self.desk)["said"])

    def test_relay_failure_names_both_virtual_environment_prefixes_but_no_duplicate(self):
        from hansa import run
        prefix = str(self.tmp / "venv")
        base = str(self.tmp / "python")
        for base_prefix in (base, prefix):
            results = [subprocess.CompletedProcess([], 2, "", "cannot read Python"),
                       subprocess.CompletedProcess([], 0, "", "")]
            with self.subTest(base_prefix=base_prefix), \
                    unittest.mock.patch.object(run.sys, "prefix", prefix), \
                    unittest.mock.patch.object(run.sys, "base_prefix", base_prefix), \
                    unittest.mock.patch.object(run.subprocess, "run", side_effect=results), \
                    self.assertRaises(run.SrtCannotRun) as failed:
                run.try_srt(self.desk, "settings.json", str(self.tmp), self.tmp)
            message = str(failed.exception)
            self.assertIn(f"prefix {prefix}", message)
            self.assertEqual(message.count(prefix), 1)
            if base_prefix != prefix:
                self.assertIn(f"base prefix {base}", message)
            else:
                self.assertNotIn("base prefix", message)

    def test_plain_true_is_tried_only_after_failure_with_the_same_srt_settings(self):
        from hansa import run
        for rc in (0, 2):
            results = [subprocess.CompletedProcess([], rc, "", "relay refused"),
                       subprocess.CompletedProcess([], 0, "", "")]
            with self.subTest(exit=rc), unittest.mock.patch.object(run.subprocess, "run", side_effect=results) as probe:
                if rc:
                    with self.assertRaises(run.SrtCannotRun):
                        run.try_srt(self.desk, "settings.json", str(self.tmp), self.tmp)
                else:
                    self.assertEqual(run.try_srt(self.desk, "settings.json", str(self.tmp), self.tmp), self.srt)
            self.assertEqual(probe.call_count, 2 if rc else 1)
            first = probe.call_args_list[0]
            self.assertEqual(first.args[0], [self.srt, "--settings", "settings.json", "--", *run.protected(["true"])])
            self.assertEqual(run.srt_record(self.desk)["ran"], rc == 0)
            if rc:
                second = probe.call_args_list[1]
                self.assertEqual(second.args[0], [self.srt, "--settings", "settings.json", "--", "true"])
                self.assertEqual(second.kwargs, first.kwargs)

    def test_timeout_and_oserror_keep_their_diagnostics_on_either_try(self):
        from hansa import run
        failures = [(subprocess.TimeoutExpired("srt", 1), f"no answer in {run.SRT_TRY_SECONDS} s"),
                    (OSError("cannot start Python"), "cannot start Python")]
        for error, said in failures:
            for first in (subprocess.CompletedProcess([], 2, "", "relay refused"), error):
                with self.subTest(error=error, first=first), \
                        unittest.mock.patch.object(run.subprocess, "run", side_effect=[first, error]) as probe, \
                        self.assertRaises(run.SrtCannotRun) as failed:
                    run.try_srt(self.desk, "settings.json", str(self.tmp), self.tmp)
                self.assertEqual(probe.call_count, 2)
                self.assertIn("could not start", str(failed.exception))
                self.assertIn(said, str(failed.exception))
                self.assertNotIn("workers may not read", str(failed.exception))
                self.assertEqual(run.srt_record(self.desk)["said"], said)


class DeskTest(unittest.TestCase):
    def setUp(self):
        started = time.time()
        self.tmp = Path(tempfile.mkdtemp())
        # registered first, so it runs last: after the other cleanups have stopped what the test started, and
        # after the followers of its desk (detached, each ends a moment after its session) have ended
        self.addCleanup(shutil.rmtree, self.tmp, ignore_errors=True)
        self.addCleanup(stop_started_on, self.tmp / "desk", started)
        env = unittest.mock.patch.dict(os.environ)  # what setUp and the test set in it is put back when it ends
        env.start()
        self.addCleanup(env.stop)
        self.repo = self.tmp / "repo"
        self.repo.mkdir()
        sh("git", "init", "-q", "-b", "main", cwd=self.repo)
        (self.repo / "README.md").write_text("demo\n")
        sh("git", "add", ".", cwd=self.repo)
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "init", cwd=self.repo)
        fake = self.tmp / "claude"
        fake.write_text(FAKE)
        fake.chmod(0o755)
        os.environ["HANSA_CLAUDE"] = str(fake)
        self.srt_log = self.tmp / "srt-calls.jsonl"
        (self.tmp / "bin").mkdir()
        srt = self.tmp / "bin" / "srt"
        srt.write_text(FAKE_SRT.replace("open(LOG", f"open({str(self.srt_log)!r}"))
        srt.chmod(0o755)
        path = unittest.mock.patch.dict(os.environ, {"PATH": f"{self.tmp / 'bin'}{os.pathsep}{os.environ['PATH']}"})
        path.start()
        self.addCleanup(path.stop)
        # not the Claude Code session the tests may run in: a stand-in (self.session) plays one where needed,
        # and what hansa would post to an inbox is caught in a file (self.posts). Nor the hansa run they may run
        # in (the suite run by a worker): its lane's env file, which its sandbox may keep the tests' runs from
        # reading, and its task and desk, so the tests give inside a worker what they give in the lane's check
        for k in ("CLAUDE_PID", "CLAUDE_CODE_MESSAGING_SOCKET", "CLAUDE_CODE_MESSAGING_TOKEN", "CLAUDE_ENV_FILE",
                  "HANSA_TASK", "HANSA_DESK", "HANSA_ROLE"):
            os.environ.pop(k, None)
        session = unittest.mock.patch.dict(hansa.SESSION, clear=True)  # what hansa took out as it was imported here
        session.start()
        self.addCleanup(session.stop)
        os.environ.update(HANSA_NOTIFY_CAPTURE=str(self.tmp / "posted.jsonl"), HANSA_NOTIFY_POLL="0.2",
                          HANSA_NOTIFY_GATHER="0.5",
                          XDG_RUNTIME_DIR=str(self.tmp))  # the inboxes' folder (notify.socket_path), not the account's
        self.desk = init_desk(self.tmp / "desk", str(self.repo), "a")
        # free space as the tests set it (self.free, in bytes, or by path: self.free_at), never the machine's: hansa
        # serve starts nothing new under the desk's floor of free space (hansa/disk.py). The volumes' size: self.total
        # (None: not known)
        self.free, self.free_at, self.total = 500 * 10 ** 9, {}, 10 ** 12
        usage = unittest.mock.patch("shutil.disk_usage", lambda p: types.SimpleNamespace(
            total=self.total, used=(self.total or 0) - self.free_for(p), free=self.free_for(p)))
        usage.start()
        self.addCleanup(usage.stop)
        if not tmp_writable():  # inside a sandbox that keeps /tmp closed: the workers' folders go in the test's own
            root = unittest.mock.patch("hansa.run.WORKER_TMP_ROOT", str(self.tmp))
            root.start()
            self.addCleanup(root.stop)

    def free_for(self, path) -> int:
        """The free space the stand-in for shutil.disk_usage gives this path: self.free_at's, for a path under one of
        its folders, else self.free."""
        return next((v for k, v in self.free_at.items()
                     if os.path.realpath(path).startswith(os.path.realpath(k))), self.free)

    def srt_calls(self, tries=False, sandbox=False) -> list:
        """What srt was called to run; tries: also hansa's runs of `true` to see that srt starts; sandbox: only its
        tries of a worker's, a verifier's or a design session's sandbox, on /usr/bin/true and writing what git needs
        open (run.try_sandbox)."""
        calls = [json.loads(x) for x in self.srt_log.read_text().splitlines()] if self.srt_log.exists() else []
        tried = lambda c: c["argv"][-2:] == ["--", "/usr/bin/true"] or c["argv"][-1].endswith("/hansa-git-open-try.sh")
        if sandbox:
            return [c for c in calls if tried(c)]
        calls = [c for c in calls if not tried(c)]
        return [c for c in calls if tries or c["argv"][-2:] != ["--", "true"]]

    def commands_tmp(self, call, allow) -> str:
        """The TMPDIR a lane's command saw after the prelude, given a stand-in srt call: srt's (the run's folder),
        or on Linux the command's own on disk that its link leads to (run.run_tmp), which it may write too."""
        from hansa import run
        if not account.LINUX:
            return call["tmpdir"]
        own = call["tmp_link"]  # run.RUN_TMP_LINK in the run's folder, as the stand-in srt found it
        self.assertEqual(Path(own).parent, self.desk.state_dir / run.RUN_TMP_DIR)
        self.assertIn(own, allow)
        return os.path.realpath(own)

    @staticmethod
    def ran(call) -> str:
        """The command a stand-in srt call was given, as the lane has it: without the prelude hansa runs in front
        of it (run.with_prelude), the lane's env still set by env as hansa sets it."""
        from hansa import run
        cmd = call["argv"][-1]

        def bare(x):
            head = run.sandbox_prelude() + "exec /bin/sh -c "
            assert x.startswith(head), x[:200]
            [inner] = shlex.split(x[len(head):])
            return inner
        if cmd.startswith("exec /usr/bin/env "):
            words = shlex.split(cmd)
            return " ".join(shlex.quote(w) for w in words[:-1]) + " " + shlex.quote(bare(words[-1]))
        return bare(cmd)

    def without_srt(self):
        """PATH without the stand-in srt, or any other."""
        keep = [d for d in os.environ["PATH"].split(os.pathsep) if d and not (Path(d) / "srt").exists()]
        return unittest.mock.patch.dict(os.environ, {"PATH": os.pathsep.join(keep)})

    def design_worktree(self, tid) -> str:
        """Lane a's design worktree on task tid's branch, made as start_design makes it."""
        from hansa import run
        lane = self.desk.settings()["lanes"]["a"]
        return str(run.prepare(self.desk, "a", lane, self.desk.meta(tid), wt=self.desk.worktrees_dir / "a-design")[0])

    def settle(self, d, tid, timeout=20):
        end = time.time() + timeout
        while time.time() < end:
            d.tick()
            if self.desk.meta(tid)["state"] not in ("queued", "running"):
                return self.desk.meta(tid)
            time.sleep(0.1)
        self.fail(f"{tid} did not finish: {self.desk.meta(tid)}")

    def test_task_runs_is_recorded_and_merges(self):
        tid = self.desk.new_task("Add hello.txt")
        m = self.settle(Dispatcher(self.desk), tid)
        self.assertEqual(m["state"], "done", m)
        self.assertEqual(m["files"], ["hello.txt"])
        self.assertGreaterEqual(m["commits"], 1)  # left uncommitted by the worker, committed by hansa
        self.assertEqual(m["denials"], ["Bash: env JAVA_HOME=/x mvn test"])
        self.assertIn("hello.txt", views.show_text(self.desk, tid))
        self.assertEqual(main(["--desk", str(self.desk.root), "merge", tid]), 0)
        self.assertEqual(self.desk.meta(tid)["state"], "merged")
        self.assertTrue((self.repo / "hello.txt").exists())

    def assert_oom_launches(self, linux):
        from hansa import release, run
        kinds = ("worker", "verification", "setup", "check", "merge check", "merge setup", "try", "resume", "release")
        popen = subprocess.Popen
        for kind in kinds:
            with self.subTest(kind=kind, linux=linux):
                folder = self.tmp / kind.replace(" ", "-")
                folder.mkdir()
                repo = folder / "repo"
                sh("git", "clone", "-q", str(self.repo), str(repo), cwd=folder)
                desk = init_desk(folder / "desk", str(repo), "a")
                s = desk.settings()
                s["lanes"]["a"].update(check="true", merge_check="true", release="true",
                                         setup="true" if kind in ("setup", "merge setup", "try") else "")
                self.assertEqual(desk.save_settings(s), [])
                lane = desk.settings()["lanes"]["a"]
                calls = []

                def launch(argv, **kwargs):
                    if not kwargs.get("start_new_session"):
                        return popen(argv, **kwargs)
                    self.assertNotIn("preexec_fn", kwargs)
                    calls.append(argv)
                    # Capture the real launch site without executing its commands or leaving work running.
                    proc = popen(["/usr/bin/true"], **kwargs)
                    proc.wait(timeout=10)
                    return proc

                with unittest.mock.patch.object(account, "LINUX", linux), \
                        unittest.mock.patch.object(subprocess, "Popen", side_effect=launch):
                    if kind == "release":
                        r = release.ask(desk, "a")
                        self.assertEqual(release.answer(desk, r["id"], True, commit=r["commit"], command=r["command"]),
                                         {"ok": True})
                        self.assertIsNotNone(release.start(desk, r["id"]))
                    elif kind == "try":
                        run.write_try(desk, "a", {"phase": "queued"})
                        self.assertIsNotNone(run.start_try(desk, "a", lane))
                        for tmp in run.read_try(desk, "a")["tmp"]:
                            self.addCleanup(shutil.rmtree, tmp, ignore_errors=True)
                    else:
                        tid = desk.new_task("Launch fixture", lane="a", kind="verify" if kind == "verification" else "work")
                        self.addCleanup(run.remove_sandbox_tmp, desk, tid)
                        if kind == "check":
                            wt = run.prepare(desk, "a", lane, desk.meta(tid))[0]
                            desk.update(tid, state="running", phase="checking", provider="claude", worktree=str(wt))
                            self.assertIsNotNone(run.start_check(desk, tid, "a", lane))
                        elif kind in ("merge check", "merge setup"):
                            head = sh_out("git", "rev-parse", "HEAD", cwd=repo)
                            sh("git", "branch", f"task/{tid}", head, cwd=repo)
                            desk.update(tid, state="merging", provider="claude", head=head, branch=f"task/{tid}",
                                        merge_check={"phase": "queued"})
                            self.assertIsNotNone(run.start_merge_check(desk, tid, "a", lane))
                        else:
                            self.assertIsNotNone(run.start(desk, tid, "a", "claude"))
                            if kind == "resume":
                                write_json(desk.raw_dir(tid) / "run.json", {"subtype": "success"})
                                with unittest.mock.patch.object(run, "read_detail", return_value=["leftover command"]):
                                    self.assertIsNotNone(run.resume(desk, tid))
                                calls.pop(0)  # check the resumed launch independently of the first start
                self.assertEqual(len(calls), 1)
                argv = calls[0]
                if linux and kind != "release":
                    self.assertEqual(argv[:4], ["/bin/sh", "-c",
                                               '{ printf "500\\n" > /proc/self/oom_score_adj; } 2>/dev/null || :\nexec "$@"',
                                               "hansa-oom"])
                    argv = argv[4:]
                else:
                    self.assertNotIn("hansa-oom", argv)
                    self.assertNotIn("/proc/self/oom_score_adj", " ".join(argv))
                # The original command stays intact, outside srt and before any setup.
                scripts = {"setup": run.SETUP_SCRIPT, "merge setup": run.SETUP_SCRIPT,
                           "check": run.CHECK_SCRIPT, "merge check": run.CHECK_SCRIPT,
                           "try": run.TRY_SCRIPT, "release": release.SCRIPT}
                if kind in scripts:
                    self.assertEqual(argv[:3], ["/bin/sh", "-c", scripts[kind]])
                else:
                    expected = json.loads((desk.raw_dir(tid) / run.RESUME_ARGV).read_text())
                    if kind == "resume":
                        expected[expected.index("--session-id")] = "--resume"
                    self.assertEqual(argv, expected)

    def test_linux_run_command_lines_raise_the_oom_score_but_releases_do_not(self):
        self.assert_oom_launches(linux=True)

    def test_macos_run_command_lines_keep_the_original_commands(self):
        self.assert_oom_launches(linux=False)

    def test_a_refused_oom_score_write_still_executes_the_command(self):
        from hansa import run
        script = run.OOM_SCRIPT.replace("/proc/self/oom_score_adj", str(self.tmp / "missing" / "oom_score_adj"))
        with unittest.mock.patch.object(account, "LINUX", True), \
                unittest.mock.patch.object(run, "OOM_SCRIPT", script):
            argv = run.with_oom_score([sys.executable, "-c", "import sys; print(sys.argv[1]); sys.exit(7)",
                                       "an argument with spaces; $still_literal"])
        self.assertEqual(argv[:4], ["/bin/sh", "-c", script, "hansa-oom"])
        result = subprocess.run(argv, capture_output=True, text=True)
        self.assertEqual(result.returncode, 7)
        self.assertEqual(result.stdout, "an argument with spaces; $still_literal\n")
        self.assertEqual(result.stderr, "")

    @unittest.skipUnless(sys.platform.startswith("linux"), "oom_score_adj is Linux only")
    def test_a_linux_worker_reads_its_own_oom_score_as_500(self):
        # Probe in a child, independently of hansa's wrapper, without changing the suite's score.
        probe = subprocess.run([sys.executable, "-c", textwrap.dedent('''\
            import sys
            try:
                with open("/proc/self/oom_score_adj", "w") as f:
                    f.write("500\\n")
            except OSError as e:
                print(e)
                sys.exit(1)
            ''')], capture_output=True, text=True)
        if probe.returncode == 1:
            self.skipTest(f"writing /proc/self/oom_score_adj is refused here: {probe.stdout.strip()}")
        self.assertEqual(probe.returncode, 0, probe.stderr)
        parent_score = Path("/proc/self/oom_score_adj").read_text()
        if int(parent_score) >= 500:  # a worker inherits it: 500 would show without hansa's wrapper
            self.skipTest(f"the suite itself already runs at oom_score_adj {parent_score.strip()}, as in a lane's check")
        fake = self.tmp / "claude"
        fake.write_text(f"#!{sys.executable}\n" + textwrap.dedent('''\
            import json, sys
            sys.stdin.read()
            with open("/proc/self/oom_score_adj") as f:
                score = int(f.read())
            print(json.dumps({"type": "result", "subtype": "success", "is_error": False,
                              "result": str(score)}))
            '''))
        tid = self.desk.new_task("Read the worker's OOM score")
        m = self.settle(Dispatcher(self.desk), tid)
        self.assertEqual(m["state"], "done", m)
        self.assertEqual((self.desk.tasks_dir / tid / "result.md").read_text().strip(), "500")
        self.assertEqual(Path("/proc/self/oom_score_adj").read_text(), parent_score)

    def test_the_oom_wrapper_gives_way_to_the_command_so_the_recorded_pid_is_the_commands(self):
        from hansa import run
        ready = self.tmp / "worker-pid"
        fake = self.tmp / "claude"
        fake.write_text(f"#!{sys.executable}\n" + textwrap.dedent(f'''\
            import os, sys, time
            sys.stdin.read()
            open({str(ready)!r} + ".part", "w").write(str(os.getpid()))
            os.replace({str(ready)!r} + ".part", {str(ready)!r})
            time.sleep(60)
            '''))
        tid = self.desk.new_task("Stay running")
        self.addCleanup(run.remove_sandbox_tmp, self.desk, tid)
        # bash and dash exec a -c string's last command by themselves: a command after it, which never runs
        # once the script execs, makes the script's own exec what gives the worker the shell's pid
        with unittest.mock.patch.object(account, "LINUX", True), \
                unittest.mock.patch.object(run, "OOM_SCRIPT", run.OOM_SCRIPT + "\n:"):
            proc = run.start(self.desk, tid, "a", "claude")
        self.addCleanup(proc.wait, timeout=10)
        self.addCleanup(proc.kill)
        end = time.time() + 20
        while not ready.exists() and proc.poll() is None and time.time() < end:
            time.sleep(0.05)
        self.assertTrue(ready.exists(), (self.desk.raw_dir(tid) / "run.err").read_text())
        pid = self.desk.meta(tid)["pid"]
        self.assertEqual(pid, proc.pid)
        self.assertEqual(pid, int(ready.read_text()))  # without exec, the shell's pid, and the worker its child
        args = run._args(pid)
        self.assertIn(str(fake), args)
        self.assertNotIn("hansa-oom", args)
        self.assertNotIn("/bin/sh", args)

    def test_a_program_that_cannot_be_found_fails_to_start_as_it_did_without_the_oom_wrapper(self):
        from hansa import run
        said = {}
        for linux in (False, True):
            for missing in (str(self.tmp / "no-such-claude"), "hansa-no-such-claude"):
                with self.subTest(linux=linux, missing=missing):
                    tid = self.desk.new_task("Start a missing program")
                    # gone after claude_bin found it, or never found by Popen: claude_bin's own fallback would be the real one
                    with unittest.mock.patch.object(account, "LINUX", linux), \
                            unittest.mock.patch.object(run, "claude_bin", lambda: missing):
                        self.assertEqual(run.with_oom_score([missing, "-p"], str(self.tmp), dict(os.environ)),
                                         [missing, "-p"])
                        Dispatcher(self.desk).tick()
                    m = self.desk.meta(tid)
                    self.assertEqual(m["state"], "failed", m)
                    self.assertIn(missing, m["error"])
                    self.assertNotIn("hansa-oom", m["error"])
                    said[linux, missing] = m["error"]
        for missing in (str(self.tmp / "no-such-claude"), "hansa-no-such-claude"):
            self.assertEqual(said[True, missing], said[False, missing])
        # one that is found is still wrapped
        with unittest.mock.patch.object(account, "LINUX", True):
            self.assertEqual(run.with_oom_score(["sh", "-c", "true"], str(self.tmp), dict(os.environ))[3:],
                             ["hansa-oom", "sh", "-c", "true"])

    def test_show_gives_the_text_hansa_read_queued_running_and_finished(self):
        f = self.tmp / "task.md"
        f.write_text("Add hello.txt\n" + "".join(f"line {i}\n" for i in range(2, 13)))
        self.hansa("add", "--file", str(f))
        f.write_text("Edited after it was queued\n")  # read when it was queued: this changes nothing
        tid = "t0001"
        cut = f"  (9 more lines; the whole text: hansa show {tid} --full)"
        for state in ("queued", "running"):
            if state == "running":
                self.desk.update(tid, state="running", phase="starting", started=now())
            shown = self.hansa("show", tid)
            self.assertIn("text (as hansa read it when it was queued", shown)
            self.assertIn("\n  Add hello.txt\n  line 2\n", shown)
            self.assertIn("\n  line 3\n" + cut + "\n", shown)
            self.assertNotIn("line 4", shown)  # not the whole text each time: enough to know the task
            self.assertNotIn("Edited", shown)
            self.assertIn("  line 12\n", self.hansa("show", tid, "--full"))
            self.assertEqual(self.hansa("show", tid, "--report").strip(), f"(no report: {tid} is {state})")
        self.desk.update(tid, state="queued", phase="", started=None)
        m = self.settle(Dispatcher(self.desk), tid)
        self.assertEqual(m["state"], "done", m)
        report = "".join(f"said {i}\n" for i in range(70))
        (self.desk.tasks_dir / tid / "result.md").write_text(report)
        shown = self.hansa("show", tid)
        self.assertIn("\n  Add hello.txt\n", shown)
        self.assertIn(cut, shown)
        self.assertIn("  said 0\n", shown)
        self.assertIn("  said 69\n", shown)  # the report whole: it is what show is run for
        self.assertNotIn("more lines; the whole report", shown)
        self.assertNotIn(str(self.desk.tasks_dir), shown)
        full = self.hansa("show", tid, "--full")
        self.assertIn("  line 12\n", full)
        self.assertIn("  said 69\n", full)
        self.assertNotIn("more lines", full)
        self.assertEqual(self.hansa("show", tid, "--report").strip(), report.strip())  # the report and nothing else
        long = "".join(f"said {i}\n" for i in range(views.REPORT_LINES + 5))
        (self.desk.tasks_dir / tid / "result.md").write_text(long)
        shown = self.hansa("show", tid)
        self.assertIn(f"  ... 5 more lines; the whole report: hansa show {tid} --report", shown)
        self.assertNotIn(f"said {views.REPORT_LINES}\n", shown)
        self.assertEqual(self.hansa("show", tid, "--report").strip(), long.strip())
        wide = "".join("x" * 1000 + f" {i}\n" for i in range(60))  # few lines, but too long to show whole
        (self.desk.tasks_dir / tid / "result.md").write_text(wide)
        shown = self.hansa("show", tid)
        self.assertIn(f"more lines; the whole report: hansa show {tid} --report", shown)
        self.assertLess(len(shown), views.REPORT_CHARS + 5000)
        self.assertEqual(self.hansa("show", tid, "--report").strip(), wide.strip())
        one = "y" * 50000  # one line alone longer than the limit: cut there too
        (self.desk.tasks_dir / tid / "result.md").write_text(one + "\n")
        shown = self.hansa("show", tid)
        self.assertIn("  " + "y" * views.REPORT_CHARS + "\n", shown)
        self.assertNotIn("y" * (views.REPORT_CHARS + 1), shown)
        self.assertIn(f"  ... {50000 - views.REPORT_CHARS} more characters of this line; the whole report: "
                      f"hansa show {tid} --report", shown)
        self.assertEqual(self.hansa("show", tid, "--report").strip(), one)
        (self.desk.tasks_dir / tid / "result.md").write_text(f"first\nsecond\n{one}\nfourth\n")
        shown = self.hansa("show", tid)
        self.assertIn("  first\n  second\n  yyy", shown)
        self.assertNotIn("fourth", shown)
        kept = views.REPORT_CHARS - len("first\nsecond\n")
        self.assertIn("  " + "y" * kept + "\n", shown)
        self.assertNotIn("y" * (kept + 1), shown)
        self.assertIn(f"  ... {50000 - kept} more characters of this line and 1 more line; the whole report: "
                      f"hansa show {tid} --report", shown)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), self.assertRaises(SystemExit):
            main(["add", "--help"])
        self.assertIn("It is read when the task is queued", " ".join(out.getvalue().split()))

    def test_hansa_commits_for_the_worker_and_keeps_git_rules_from_it(self):
        seen = self.tmp / "argv.jsonl"
        s = self.desk.settings()
        s["lanes"]["a"]["allow"] = ["Bash(git commit:*)", "Bash(pnpm test:*)"]  # saved before hansa took over git
        s["lanes"]["a"]["env"] = {"FAKE_SHOW_ARGV": str(seen)}
        self.desk.settings_path.write_text(json.dumps(s))
        self.assertTrue(any("git is handled by hansa" in p for p in validate(s)))  # the page refuses new ones
        tid = self.desk.new_task("Add hello.txt", title="Add a greeting")
        m = self.settle(Dispatcher(self.desk), tid)
        argv = json.loads(seen.read_text().splitlines()[-1])
        self.assertNotIn("Bash(git commit:*)", argv[argv.index("--allowedTools"):])
        self.assertIn("Bash(pnpm test:*)", argv)
        self.assertIn("hansa commits", argv[argv.index("--append-system-prompt") + 1])
        msg = subprocess.run(["git", "log", "-1", "--format=%s", m["head"]], cwd=self.repo,
                             capture_output=True, text=True).stdout.strip()
        self.assertEqual(msg, f"{tid}: Add a greeting")
        self.assertIn("ignored", views.explain_text(self.desk, "lane", "a"))

    def test_hansas_commit_leaves_out_the_claude_folder_a_sandbox_left(self):
        from hansa import run
        s = self.desk.settings()
        s["lanes"]["a"]["env"] = {"FAKE_SANDBOX_LEFT": "1", "FAKE_WRITE": "worker's own", "FAKE_WRITE_FILE": "notes.md"}
        self.assertEqual(self.desk.save_settings(s), [])
        tid = self.desk.new_task("Add hello.txt")
        m = self.settle(Dispatcher(self.desk), tid)
        self.assertEqual((m["state"], m["files"]), ("done", ["hello.txt", "notes.md"]), m)
        wt = Path(m["worktree"])
        self.assertTrue((wt / ".claude" / ".cc-writes").exists())  # left where it was, uncommitted
        self.assertTrue((wt / ".bashrc").exists())
        run.commit_work(self.desk, wt, "nothing but placeholders", f"task/{m['id']}")  # with only those there, nothing to commit
        self.assertEqual(self.git_out("rev-parse", "HEAD", cwd=wt), m["head"])
        (wt / ".gitconfig").write_text("[user]\n")
        with self.assertRaisesRegex(run.SandboxPathChanged, r"\.gitconfig"):
            run.commit_work(self.desk, wt, "protected", f"task/{m['id']}")
        self.assertEqual(self.git_out("rev-parse", "HEAD", cwd=wt), m["head"])
        (wt / ".gitconfig").write_text("")
        (wt / "sub").mkdir()
        (wt / "sub" / ".bashrc").write_text("")
        run.commit_work(self.desk, wt, "a real one", f"task/{m['id']}")
        self.assertEqual(sorted(self.git_out("show", "--name-only", "--format=", "HEAD", cwd=wt).split()),
                         ["sub/.bashrc"])
        for text in (run.PROTOCOL, run.VERIFY_PROTOCOL):  # workers are told of those under .claude/, and to leave them
            flat = " ".join(text.split())
            self.assertIn(".claude/", flat)
            self.assertIn("hansa never commits them", flat)
            for name in run.SANDBOX_PLACEHOLDERS:  # git in the sandbox does not list these (LINUX_PRELUDE)
                self.assertNotIn(name, flat)

    # Protected-index regression cases (the numbers match the requested table):
    # | # | Case | Test below |
    # | 1 | cacheinfo .claude/settings.json, absent on disk, skip-worktree | protected_blobs |
    # | 2 | .mcp.json, .vscode/settings.json, .Claude/Settings.json | protected_blobs |
    # | 3 | tracked, newly ignored .gitmodules removed from index | protected_deletions |
    # | 4 | newly ignored .claude/agents/x.md renamed through index | protected_deletions |
    # | 5 | retry --update carries the base's protected change | retry_update below |
    # | 6 | lane remove --keep holds a staged .idea/x.xml | lane_remove below |
    # | 7 | ordinary add/change/delete/rename and .vscodex | ordinary_work |
    # | 8 | worker-staged empty .bashrc and .claude/settings.json | staged_placeholders |

    def protected_worktree(self, kind="task"):
        from hansa import run
        tid = self.desk.new_task("Work on ordinary files", kind=kind, lane="a")
        lane = self.desk.settings()["lanes"]["a"]
        wt = Path(self.design_worktree(tid)) if kind == "design" else run.prepare(
            self.desk, "a", lane, self.desk.meta(tid))[0]
        base = self.git_out("rev-parse", "HEAD", cwd=wt)
        self.desk.update(tid, state="running", lane="a", provider="claude", worktree=str(wt),
                         session_id="sid-x", branch=f"task/{tid}", base=base)
        write_json(self.desk.raw_dir(tid) / "run.json", {"subtype": "success", "result": "Work finished."})
        return tid, wt, base

    def stage_protected_blob(self, wt, path, mode="100644"):
        blob = self.git_out("rev-parse", "HEAD:README.md", cwd=wt)
        sh("git", "update-index", "--add", "--cacheinfo", f"{mode},{blob},{path}", cwd=wt)
        sh("git", "update-index", "--skip-worktree", "--", path, cwd=wt)
        self.assertFalse(os.path.lexists(wt / path))
        return blob

    def assert_protected_finish(self, tid, wt, base, paths):
        from hansa import run
        (wt / "ordinary.txt").write_text("work must remain uncommitted\n")
        before = self.git_out("rev-list", "--all", cwd=wt)
        m = run.finish(self.desk, tid, 0)
        self.assertEqual(m["state"], "failed", m)
        self.assertEqual(m["error"],
                         f"refusing to commit changes to protected paths: {', '.join(sorted(paths))}; the workers' "
                         "sandbox does not let them write these paths, so the changes can only have come through "
                         "git's index; nothing was committed; the work is left staged. To change these paths, "
                         "ask the principal: they change them outside a task")
        self.assertEqual(self.git_out("rev-parse", f"task/{tid}"), base)
        self.assertEqual(self.git_out("rev-list", "--all", cwd=wt), before)
        self.assertIn("ordinary.txt", self.git_out("diff", "--cached", "--name-only", cwd=wt))
        self.assertEqual((m["head"], m["commits"], m["files"]), ("", 0, []))

    def test_hansas_commit_refuses_protected_blobs_in_the_index(self):
        from hansa import run
        paths = [".claude/settings.json", ".mcp.json", ".vscode/settings.json", ".Claude/Settings.json"]
        # Both worker runs and design sessions' end use the rule. Test all roots and link types too.
        paths += [p for p in run.SANDBOX_PROTECTED_PATHS if p not in paths]
        for kind in ("task", "design"):
            for path in paths:
                with self.subTest(kind=kind, path=path):
                    tid, wt, base = self.protected_worktree(kind)
                    blob = self.stage_protected_blob(wt, path)
                    self.assert_protected_finish(tid, wt, base, [path])
                    self.assertEqual(self.git_out("rev-parse", f":{path}", cwd=wt), blob)

    def test_hansas_commit_refuses_protected_deletions_and_renames_in_the_index(self):
        for path, rename in ((".gitmodules", False), (".claude/agents/x.md", True)):
            with self.subTest(path=path):
                # The principal adds a tracked file to the base outside a task.
                target = self.repo / path
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text("tracked content\n")
                sh("git", "add", "--", path, cwd=self.repo)
                sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "principal", cwd=self.repo)
                tid, wt, base = self.protected_worktree()
                (wt / ".gitignore").write_text(path + "\n")
                blob = self.git_out("rev-parse", f"HEAD:{path}", cwd=wt)
                sh("git", "rm", "--cached", "--", path, cwd=wt)
                if rename:
                    sh("git", "update-index", "--add", "--cacheinfo", f"100644,{blob},docs/x.md", cwd=wt)
                    sh("git", "update-index", "--skip-worktree", "--", "docs/x.md", cwd=wt)
                    self.assertIn("R100", self.git_out("diff", "--cached", "--name-status", "-M", cwd=wt))
                self.assert_protected_finish(tid, wt, base, [path])
                self.assertTrue((wt / path).is_file())
                self.assertIn(path, self.git_out("diff", "--cached", "--name-only", "--no-renames", cwd=wt))

    def test_hansas_commit_keeps_ordinary_work_outside_protected_paths(self):
        from hansa import run
        for name in ("changed.txt", "deleted.txt", "before.txt"):
            (self.repo / name).write_text(name + "\n")
        sh("git", "add", "-A", cwd=self.repo)
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "ordinary base", cwd=self.repo)
        tid, wt, base = self.protected_worktree()
        (wt / "changed.txt").write_text("changed\n")
        (wt / "deleted.txt").unlink()
        (wt / "before.txt").rename(wt / "after.txt")
        for name in ("added.txt", ".vscodex", ".claudex", "sub/.mcp.json"):
            (wt / name).parent.mkdir(parents=True, exist_ok=True)
            (wt / name).write_text("ordinary\n")
        m = run.finish(self.desk, tid, 0)
        self.assertEqual(m["state"], "done", m)
        self.assertNotEqual(m["head"], base)
        self.assertEqual(set(m["files"]), {"changed.txt", "deleted.txt", "after.txt", "added.txt",
                                          ".vscodex", ".claudex", "sub/.mcp.json"})
        self.assertIn("R100", self.git_out("diff", "--name-status", "-M", base, m["head"], cwd=wt))

    def test_hansas_commit_leaves_out_worker_staged_placeholders(self):
        from hansa import run
        tid, wt, base = self.protected_worktree()
        paths = (".bashrc", ".claude/settings.json", ".Claude/Agents/empty.md")
        for path in paths:
            (wt / path).parent.mkdir(parents=True, exist_ok=True)
            (wt / path).write_text("")
        (wt / "ordinary.txt").write_text("work\n")
        sh("git", "add", "-A", cwd=wt)
        m = run.finish(self.desk, tid, 0)
        self.assertEqual((m["state"], m["files"]), ("done", ["ordinary.txt"]), m)
        self.assertNotEqual(m["head"], base)
        for path in paths:
            self.assertTrue((wt / path).is_file())
            self.assertNotIn(path, self.git_out("ls-files", cwd=wt))

    def test_hansas_commit_names_every_protected_path_and_refuses_link_types(self):
        tid, wt, base = self.protected_worktree("design")
        paths = [".idea/" + "x" * 180 + ".xml", ".vscode/" + "y" * 180 + ".json", ".claude"]
        for path in paths:
            self.stage_protected_blob(wt, path, "120000" if path == ".claude" else "100644")
        self.assert_protected_finish(tid, wt, base, paths)  # full list, even beyond 300 characters

    def test_hansas_commit_refuses_tracked_protected_changes_and_folder_to_link(self):
        path = ".claude/agents/x.md"
        target = self.repo / path
        target.parent.mkdir(parents=True)
        target.write_text("tracked\n")
        sh("git", "add", "--", path, cwd=self.repo)
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "principal agent", cwd=self.repo)
        tid, wt, base = self.protected_worktree()
        (wt / path).write_text("")  # tracked empty files are changes, not sandbox placeholders
        self.assert_protected_finish(tid, wt, base, [path])
        tid, wt, base = self.protected_worktree()
        (wt / ".gitignore").write_text(path + "\n")
        sh("git", "rm", "--cached", "--", path, cwd=wt)
        blob = self.git_out("rev-parse", "HEAD:README.md", cwd=wt)
        sh("git", "update-index", "--add", "--cacheinfo", f"120000,{blob},.claude", cwd=wt)
        sh("git", "update-index", "--skip-worktree", "--", ".claude", cwd=wt)
        self.assert_protected_finish(tid, wt, base, [".claude", path])

    def test_hansas_commit_accepts_only_the_merged_bases_content_and_mode(self):
        from hansa import run
        for name, mode, same_blob in (("same", "100644", True), ("mode", "100755", True),
                                      ("content", "100644", False)):
            with self.subTest(name=name):
                tid, wt, old = self.protected_worktree()
                path = f".claude/{name}.json"
                target = self.repo / path
                target.parent.mkdir(exist_ok=True)
                target.write_text("demo\n")  # README's blob is already in the repository
                sh("git", "add", "--", path, cwd=self.repo)
                sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "base settings", cwd=self.repo)
                base = self.git_out("rev-parse", "main")
                blob = self.stage_protected_blob(wt, path, mode)
                if not same_blob:
                    # A different existing blob, without writing the protected file on disk.
                    (wt / "other.txt").write_text("different\n")
                    blob = self.git_out("hash-object", "-w", "other.txt", cwd=wt)
                    sh("git", "update-index", "--cacheinfo", f"{mode},{blob},{path}", cwd=wt)
                    sh("git", "update-index", "--skip-worktree", "--", path, cwd=wt)
                if mode == "100644" and same_blob:
                    head = run.commit_work(self.desk, wt, "merged base", f"task/{tid}", [base])
                    self.assertEqual(self.git_out("rev-list", "--parents", "-n", "1", head).split()[1:], [old, base])
                else:
                    with self.assertRaisesRegex(run.SandboxPathChanged, re.escape(path)):
                        run.commit_work(self.desk, wt, "changed base", f"task/{tid}", [base])
                    self.assertEqual(self.git_out("rev-parse", f"task/{tid}"), old)

    def test_workers_are_told_git_stash_is_refused_and_background_work_ends_in_its_command(self):
        from hansa import run
        for text in (run.PROTOCOL, run.VERIFY_PROTOCOL):
            flat = " ".join(text.split())
            self.assertIn("`git stash` is refused, `git stash list` too, and one refused part refuses the whole "
                          "command line", flat)
            self.assertIn("`git show HEAD:path`", flat)
            self.assertIn("stop background work within the command that started it, or wait for it there", flat)
            text.format(tid="t1", lane="a", tmp="/tmp/x", long="")  # still a template with nothing else to fill

    def test_a_change_holding_a_stored_key_is_never_merged_and_the_key_is_never_shown(self):
        key = "sk-test-0123456789"
        self.desk.write_key("mimo", key)
        s = self.desk.settings()
        s["lanes"]["a"]["env"] = {"FAKE_WRITE": key}
        s["lanes"]["a"]["check"] = "cat notes.txt"  # a check that prints what the change holds
        self.assertEqual(self.desk.save_settings(s), [])
        tid = self.desk.new_task("Add hello.txt")
        m = self.settle(Dispatcher(self.desk), tid)
        self.assertEqual((m["state"], m["leaked"]), ("done", ["mimo"]), m)
        shown = views.show_text(self.desk, tid)
        self.assertIn("key of mimo", shown)
        self.assertNotIn(key, shown)
        self.assertNotIn(key, views.diff_text(self.desk, tid))
        self.assertIn("key of mimo", views.diff_text(self.desk, tid))
        self.assertNotIn(key, json.dumps(m["check"]))
        self.assertNotIn(key, (self.desk.tasks_dir / tid / "check.log").read_text())
        self.assertNotIn(key, (self.desk.tasks_dir / tid / "result.md").read_text())
        self.assertNotIn(key, self.desk.events_path.read_text())
        self.assertIn("key", views.status_text(views.status(self.desk)))
        with self.assertRaises(SystemExit):
            main(["--desk", str(self.desk.root), "merge", tid, "--despite-check"])
        self.assertFalse((self.repo / "notes.txt").exists())
        self.desk.event("anything", detail=f"the endpoint said: bad key {key}")
        self.assertNotIn(key, self.desk.events_path.read_text())

    def hansa_git(self, *args):
        """(exit code, standard output, standard error) of hansa git ARGS."""
        out, err, code = io.StringIO(), io.StringIO(), 0
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                main(["--desk", str(self.desk.root), "git", *args])
            except SystemExit as e:
                code = e.code if isinstance(e.code, int) else 1
                err.write("" if isinstance(e.code, int) else str(e.code))
        return code, out.getvalue(), err.getvalue()

    def test_hansa_git_reads_a_lanes_repository_and_worktree_as_git_prints_them(self):
        key = "sk-test-0123456789"
        self.desk.write_key("mimo", key)
        s = self.desk.settings()
        s["lanes"]["a"]["env"] = {"FAKE_WRITE": key}
        self.assertEqual(self.desk.save_settings(s), [])
        tid = self.desk.new_task("Add hello.txt")
        m = self.settle(Dispatcher(self.desk), tid)
        self.assertEqual(self.hansa_git("a", "log", "--oneline", "-1"),
                         (0, self.git_out("log", "--oneline", "-1") + "\n", ""))
        code, out, _ = self.hansa_git("a", "show", f"task/{tid}", "--", "hello.txt")
        self.assertEqual((code, out), (0, self.git_out("show", f"task/{tid}", "--", "hello.txt") + "\n"))
        code, out, _ = self.hansa_git("a", "grep", "-n", "demo")
        self.assertEqual((code, out), (0, "README.md:1:demo\n"))
        both = (f"task/{tid}:hello.txt", "main:README.md")  # several files in one call, as the card says
        code, out, _ = self.hansa_git("a", "show", *both)
        self.assertEqual((code, out), (0, self.git_out("show", *both) + "\n"))
        self.assertIn("demo\n", out)
        self.assertIn(self.git_out("show", both[0]), out)
        code, out, _ = self.hansa_git("a", "grep", "-n", "-e", "demo", "-e", "nothing-here", "main", "--", ".")
        self.assertEqual((code, out), (0, "main:README.md:1:demo\n"))  # several things at once, as the card says
        code, out, _ = self.hansa_git("a", "show", f"task/{tid}:notes.txt")  # a stored key is never shown
        self.assertEqual(code, 0)
        self.assertNotIn(key, out)
        self.assertIn("[key of mimo]", out)
        (Path(m["worktree"]) / "scratch.txt").write_text("x\n")
        for args in (("a", "--worktree", "status", "--short"), ("--worktree", "a", "status", "--short")):
            self.assertEqual(self.hansa_git(*args), (0, "?? scratch.txt\n", ""))
        self.assertEqual(self.hansa_git("a", "status", "--short"), (0, "", ""))  # the repository, not the worktree
        self.assertEqual(self.hansa_git("a", "branch", "--list", "task/*")[:2], (0, f"+ task/{tid}\n"))  # in a worktree
        self.assertEqual(self.hansa_git("a", "log", "--bogus")[0], 128)  # git's own failure, as git ends
        code, _, err = self.hansa_git("z", "log")
        self.assertIn("no lane z", err)

    def hansa_notes(self, *args):
        """(exit code, standard output, what it said when it refused) of hansa notes ARGS."""
        out, code, err = io.StringIO(), 0, ""
        with contextlib.redirect_stdout(out):
            try:
                main(["--desk", str(self.desk.root), "notes", *args])
            except SystemExit as e:
                code, err = (e.code, "") if isinstance(e.code, int) else (1, str(e.code))
        return code, out.getvalue(), err

    NOTES = ("# Plan\nintro\n\n## Round 1\ndone one\n### Detail\nx\n```\n## in code, not a heading\n```\n\n"
             "## Round 2\nopen\n\n## Round 12\nlast\n")

    def notes_state(self):
        return {str(p.relative_to(self.desk.notes_dir)): p.read_bytes() for p in self.desk.notes_dir.rglob("*")
                if p.is_file()}

    def test_project_file_is_made_once_and_the_card_imports_it(self):
        project = self.desk.root / "notes" / "PROJECT.md"
        self.assertEqual(project, self.desk.project_path)
        made = project.read_text()
        self.assertEqual(len(made.splitlines()), 1)  # one line saying what it is for, as a comment Claude Code drops
        self.assertTrue(made.startswith("<!--") and made.rstrip().endswith("-->"))
        card = (self.desk.root / "CLAUDE.md").read_text()
        # on a line of its own, outside backticks: a path in a code span is not imported
        self.assertIn("\n@notes/PROJECT.md\n", card)
        project.write_text("# Rules\nnever push on Fridays\n")
        (self.desk.root / "CLAUDE.md").write_text("an older card\n")
        cli.coordinator_desk(self.desk, os.getuid())  # the card refreshed: the import comes back, the file is left
        self.assertIn("\n@notes/PROJECT.md\n", (self.desk.root / "CLAUDE.md").read_text())
        self.assertIn("card_refreshed", self.desk.events_path.read_text())
        self.assertEqual(project.read_text(), "# Rules\nnever push on Fridays\n")
        project.unlink()  # a missing file stops nothing, and hansa does not make it again
        cli.coordinator_desk(self.desk, os.getuid())
        self.assertFalse(project.exists())
        self.assertIn("\n@notes/PROJECT.md\n", (self.desk.root / "CLAUDE.md").read_text())
        st = views.status(self.desk)
        self.assertFalse(st["project"]["present"])
        self.assertIn("project rules: no notes/PROJECT.md", views.status_text(st))
        self.assertEqual(self.hansa_notes()[0], 0)

