    def test_not_logged_in_rests_provider_until_a_check_answers(self):
        from hansa import run
        s = self.desk.settings()
        s["providers"]["mimo"] = {"kind": "compatible", "model": "mimo-x", "effort": "", "base_url": "https://example.invalid"}
