        self.assertEqual(self.desk.save_settings(s), [])
        prob = provider_problem(self.desk, self.desk.settings(), "claude")
        self.assertIn("log in with `CLAUDE_CONFIG_DIR='/Users/me/claude two' claude`", prob)
