    def test_a_start_asks_git_for_a_worktrees_folders_once_unless_its_git_file_changes(self):
        from hansa import run
        wt, other = self.tmp / "wt", self.tmp / "other"
        for w in (wt, other):
            sh("git", "worktree", "add", "--detach", str(w), cwd=self.repo)
        mine, theirs = (wt / ".git").read_text(), (other / ".git").read_text()
        asked = []
        real = run.git

        def git(*args, cwd, env=None):
            asked.append(args)
            return real(*args, cwd=cwd, env=env)

        @run.git_folders_kept
        def a_start():
            first = run.git_folders(wt)
            for _ in range(3):
                run.git_write_deny(wt)
                run.git_needs_open(wt)
                self.assertEqual(run.git_folders(wt), first)
            n = len(asked)
            (wt / ".git").write_text(theirs)  # another git folder: never answered from what was kept
            moved = run.git_folders(wt)
            self.assertEqual(len(asked), n + 2)
            (wt / ".git").write_text(mine)
            return first, moved, n
        with unittest.mock.patch("hansa.run.git", git):
            first, moved, n = a_start()
            self.assertEqual(n, 2)  # once, for all the builds
            self.assertEqual(moved, run.git_folders(other))
            self.assertNotEqual(first[1].resolve(), moved[1].resolve())
            asked.clear()
            run.git_folders(wt)
            run.git_folders(wt)
            self.assertEqual(len(asked), 4)  # outside a start nothing is kept
        key = run._git_folders_key(wt)
        commondir = first[1] / "commondir"
        commondir.write_text(commondir.read_text() + "\n")
        self.assertNotEqual(run._git_folders_key(wt), key)  # nor when the commondir it leads to changes

    def test_the_git_paths_the_sandbox_keeps_are_made_when_missing(self):
        # on Linux the sandbox puts a device nobody can open where a listed path is missing, and git fails on it
        from hansa import run
        packed = self.repo / ".git" / "packed-refs"
        self.assertFalse(packed.exists())  # a repository made with git init has none until refs are packed
        m = self.settle(Dispatcher(self.desk), self.desk.new_task("Add hello.txt"))
        self.assertEqual(m["state"], "done", m)
        self.assertEqual(packed.read_text(), "")
        wt = Path(m["worktree"])
        own = Path(self.git_out("rev-parse", "--absolute-git-dir", cwd=wt))
        for f in run.GIT_OWN_DENY:  # but what says a merge is under way: an empty one would say so
            self.assertEqual((own / f).exists(), f not in run.GIT_OPS, f)
        self.assertTrue((own / "logs").is_dir())
        self.assertEqual(self.git_out("status", "--porcelain", cwd=wt), "")  # git_out fails if git does
        self.assertEqual(self.git_out("log", "--format=%H", cwd=wt).splitlines()[0], m["head"])
        self.assertEqual(self.git_out("status", "--porcelain"), "")

        sh("git", "pack-refs", "--all", cwd=self.repo)  # a repository whose packed-refs holds refs keeps them
        held = packed.read_text()
        self.assertIn("refs/heads/main", held)
        lane = self.desk.settings()["lanes"]["a"]
        pname = lane["providers"][0]
        run.lane_sandbox(self.desk, lane, pname, self.desk.settings()["providers"][pname], wt)
        self.assertEqual(packed.read_text(), held)
        self.assertIn("init", self.git_out("log", "--oneline", "main"))

    def test_a_worktree_whose_git_file_was_redirected_gets_no_git_and_is_put_right(self):
        marker = self.tmp / "hook-ran"
        s = self.desk.settings()
        s["lanes"]["a"]["env"] = {"FAKE_REDIRECT_GIT": str(marker)}
