        said = views.try_text("a", {"ok": False, "onto": "abc", "steps": {"check": {
            "ran": True, "command": "npm test", "exit": 1, "seconds": 2, "tail": ["\x1b[32m✓\x1b[39m one"]}}})
        self.assertIn("    ✓ one", said)
