    # -- the coordinator alert: what hansa posts cannot reach the coordinator's session (alert.py, notify.Watch) ------
    WATCHED = {"pid": 4242, "start": ""}  # the stand-in session the followers of these rows post to

    class Restarted(Exception):
        """A follower ran itself again on new code; args[0]: what it carried over."""

    class Named:
        """A follower's own name lookups, left out: it keeps the name it was started with and those the Watch hears."""
        def __init__(self, pid, name="", **_):
            self.name = name

        def tick(self):
            return self.name

        def heard(self, name):
            self.name = name or self.name

    def coordinator_desk(self, n, command=True, **minutes) -> Path:
        """Row n's own desk, which becomes self.desk: the stand-in alert command set on the page (unless command is
        False), and the coordinator alert's minutes as given. The stand-in claude lists the sessions FAKE_AGENTS names,
        and FAKE_AGENTS_LOG gets a line each time it runs. Returns where the alert command writes what it is given."""
        self.desk = init_desk(self.tmp / f"desk-{n}", str(self.repo), "a")
        out = self.tmp / f"alerts-{n}.jsonl"
        if command:
            script = self.tmp / "alert.py"
            script.write_text(self.ALERT_FAKE)
            cmd = f"{shlex.quote(sys.executable)} {shlex.quote(str(script))} {shlex.quote(str(out))}"
            self.assertEqual(self.page_save(lambda s: s.update(alert={"command": cmd})), {"ok": True, "problems": []})
        if minutes:
            self.assertEqual(self.page_save(lambda s: s["coordinator_alert"].update(minutes)),
                             {"ok": True, "problems": []})
        os.environ.update(FAKE_AGENTS=str(self.tmp / f"agents-{n}.json"),
                          FAKE_AGENTS_LOG=str(self.tmp / f"agents-{n}.log"))
        return out

    def agents_say(self, said) -> None:
        """What the stand-in `claude agents --json` answers from now on: {pid: status}, or text printed as it is."""
        Path(os.environ["FAKE_AGENTS"]).write_text(said if isinstance(said, str) else json.dumps(said))

    def looked_up(self) -> int:
        """How many times `claude agents --json` ran for this row."""
        f = Path(os.environ["FAKE_AGENTS_LOG"])
        return len(f.read_text().splitlines()) if f.exists() else 0

    def coordinator_task_ended(self, title) -> str:
        """A task that ended done and waits for review, as hansa serve leaves it and records it."""
        tid = self.desk.new_task(title, lane="a")
        self.desk.update(tid, state="done", finished=time.time())
        self.desk.event("task_finished", task=tid, state="done")
        return tid

    def coordinator_alerts(self) -> list:
        from hansa import alert
        return [x["text"] for x in alert.queued(self.desk) if x["kind"] == "coordinator"]

    def status_at(self, t) -> str:
        """hansa status, as it reads at time t."""
        from hansa import alert
        with unittest.mock.patch.object(alert, "time", unittest.mock.Mock(wraps=time, time=lambda: t)):
            return self.hansa_out("status")

    def follow_on_a_clock(self, minutes, at=None, start=None, restart_at=None, resume=None, step=10.0, namer=False,
                          also=()) -> tuple:
        """Run a follower of the stand-in session WATCHED (named desk-4242) in this process, on a clock the test moves
        `step` seconds each turn of its loop, from `start` (default: now) for `minutes`. at: {minute: callable}, each
        called as that minute comes (what the stand-in claude says, a task that ends, a look at hansa status). Each
        lookup it starts ends before its next turn. restart_at: the minute hansa's code changes on disk, after which it
        runs itself again on it; resume: what one that did carried, to start from. namer: with its own name lookups
        (else it keeps its name). also: the pids of more stand-in sessions (named desk-PID), each with a follower that
        runs alongside, turn by turn on the same clock. Returns (what they printed: their log, the clock at the end,
        what the first carried over a restart or None)."""
        from hansa import alert
        t0 = float(int(time.time())) if start is None else start  # whole seconds: each turn's time is exact
        clock, todo, carried, broke = [t0], sorted((at or {}).items()), [None], []
        fake = unittest.mock.Mock(wraps=time, time=lambda: clock[0])

        def turn():  # every follower is at the start of its loop's turn: the lookups they started end, the clock moves
            for th in threading.enumerate():
                if th.name == "hansa-look":
                    th.join(30)
            clock[0] += step
            while todo and todo[0][0] <= (clock[0] - t0) / 60:
                todo.pop(0)[1]()
        sessions = [(dict(self.WATCHED), "desk-4242")] + [({"pid": p, "start": ""}, f"desk-{p}") for p in also]
        together = threading.Barrier(len(sessions), action=turn)

        def gone(sess):  # each turn of its loop starts here
            together.wait(60)
            return (clock[0] - t0) / 60 >= minutes

        def restart(state):
            raise self.Restarted(state)

        def run(i, sess, name):
            try:
                notify.follow(self.desk, notify.key_of(sess), sess,
                              str(self.tmp / f"inbox-{self.desk.root.name}{f'-{i}' if i else ''}.sock"), "nonce",
                              name=name)
            except self.Restarted as e:
                if not i:
                    carried[0] = e.args[0]
            except BaseException as e:  # noqa: BLE001 - raised again below, in the test's own thread
                broke.append(e)
                together.abort()
        log = io.StringIO()
        with unittest.mock.patch.object(notify, "time", fake), unittest.mock.patch.object(alert, "time", fake), \
                unittest.mock.patch.object(notify, "now", lambda: clock[0]), \
                unittest.mock.patch.object(notify, "gone", gone), \
                unittest.mock.patch.object(notify, "code_mark", lambda: "new" if restart_at is not None
                                           and clock[0] - t0 >= restart_at * 60 else "old"), \
                unittest.mock.patch.object(notify, "CODE_SETTLE", 0), \
                unittest.mock.patch.object(notify, "_restart", restart), \
                unittest.mock.patch.object(notify, "Namer", notify.Namer if namer else self.Named), \
                unittest.mock.patch.object(notify.signal, "signal", lambda *_: None) if also else \
                contextlib.nullcontext(), \
                unittest.mock.patch.dict(os.environ, {"HANSA_NOTIFY_POLL": "0", "HANSA_NOTIFY_GATHER": "0", **(
                    {"HANSA_NOTIFY_RESUME": json.dumps(resume)} if resume else {})}), \
                contextlib.redirect_stdout(log):
            threads = [threading.Thread(target=run, args=(i, *x)) for i, x in enumerate(sessions) if i]
            for th in threads:
                th.start()
            run(0, *sessions[0])
            for th in threads:
                th.join(600)
        if broke:
            raise broke[0]
        return log.getvalue(), clock[0], carried[0]

    def test_the_principal_is_alerted_when_the_coordinators_session_cannot_be_reached(self):
        """The `coordinator` alert, one row per rule; each row runs in a desk of its own."""
        from hansa import alert

        def posted():
            return self.posts(str(self.tmp / f"inbox-{self.desk.root.name}.sock"))
        waits = "the coordinator's session pid 4242 (desk-4242) has waited on its window"

        def row1():
            """no live follower; a task ended N1 minutes ago: one alert naming the count and the oldest"""
            out = self.coordinator_desk(1)
            t = time.time()
            alert.unheard_check(self.desk, t)  # hansa serve's first look: what ends from now on counts
            self.coordinator_task_ended("Add a")
            self.coordinator_task_ended("Add b")
            a = self.events("task_finished")[0]["ts"]  # when the oldest ended
            alert.unheard_check(self.desk, a + 9 * 60)
            self.assertEqual(self.coordinator_alerts(), [])
            alert.unheard_check(self.desk, a + 10 * 60)
            [text] = self.coordinator_alerts()
            self.assertIn("the coordinator's session cannot be reached: no session hears from hansa (none has on this "
                          "desk yet) · 2 thing(s) wait for the coordinator, the oldest for 10 min: t0001 done: Add a",
                          text)
            self.assertIn("no session hears from hansa, so the coordinator's session cannot be reached: 2 thing(s) wait "
                          "for it, the oldest for 20 min (t0001 done: Add a", self.status_at(a + 20 * 60))
            for later in (11, 30, 600):  # none more while still no session hears, whatever else ends
                self.coordinator_task_ended(f"Add more at {later}")
                alert.unheard_check(self.desk, a + later * 60)
            self.assertEqual(len(self.coordinator_alerts()), 1)
            self.assertEqual(alert.send_due(self.desk, gather=0)["ok"], True)
            [sent] = self.alerted(out)
            self.assertEqual(sent["kind"], "coordinator")
            self.assertTrue(sent["text"].startswith("[hansa] desk desk-1: the coordinator's session cannot be reached"))

        def row2():
            """then a follower runs and ends, and another task ends and waits N1 minutes: a second alert"""
            self.coordinator_desk(2)
            p, _ = self.session()
            sess = {"pid": p.pid, "start": notify.proc_start(p.pid)}
            me = {"key": notify.key_of(sess), "session": sess, "uid": os.getuid(), "name": "desk-87"}
            t = time.time()
            alert.unheard_check(self.desk, t)
            self.coordinator_task_ended("Add a")
            alert.unheard_check(self.desk, t + 11 * 60)
            self.assertEqual(len(self.coordinator_alerts()), 1)
            notify.handle(self.desk, {"op": "start", "me": me})  # a follower runs: the case begins anew
            alert.unheard_check(self.desk, t + 12 * 60)
            notify.handle(self.desk, {"op": "end", "me": me, "done": notify.log_end(self.desk)})
            p.kill()
            p.wait()
            self.coordinator_task_ended("Add b")
            b = self.events("task_finished")[-1]["ts"]
            alert.unheard_check(self.desk, b + 9 * 60)  # what ended before the follower ran was told: b only
            self.assertEqual(len(self.coordinator_alerts()), 1)
            alert.unheard_check(self.desk, b + 10 * 60)
            self.assertEqual(len(self.coordinator_alerts()), 2)
            self.assertIn(f"(the last was session pid {p.pid} (desk-87), until ", self.coordinator_alerts()[1])
            self.assertIn(": its session ended) · 1 thing(s) wait for the coordinator, the oldest for 10 min: t0002 done: "
                          "Add b", self.coordinator_alerts()[1])

        def row3():
            """a live follower, the same events: no alert of the first case"""
            self.coordinator_desk(3)
            p, _ = self.session()
            self.hearing(p)
            t = time.time()
            alert.unheard_check(self.desk, t)
            self.coordinator_task_ended("Add a")
            self.coordinator_task_ended("Add b")
            for later in (11, 60, 600):
                alert.unheard_check(self.desk, t + later * 60)
            self.assertEqual(self.coordinator_alerts(), [])
            self.assertNotIn("no session hears from hansa", self.status_at(t + 60 * 60))

        def row4():
            """no alert command set: nothing runs, as for other kinds"""
            out = self.coordinator_desk(4, command=False)
            self.agents_say({"4242": "waiting"})
            t = time.time()
            alert.unheard_check(self.desk, t)
            self.coordinator_task_ended("Add a")
            alert.unheard_check(self.desk, t + 60 * 60)
            self.follow_on_a_clock(5, at={0.5: lambda: self.coordinator_task_ended("Add b")})
            self.assertEqual((alert.queued(self.desk), alert.send_due(self.desk, gather=0)), ([], None))
            self.assertFalse(out.exists())
            self.assertEqual(self.looked_up(), 0)  # with nothing to alert with, a follower looks nothing up
            self.assertEqual(len(posted()), 1)  # the session is still posted to

        def row5():
            """status waiting for N2 minutes after a post: one alert; none more in that stretch"""
            self.coordinator_desk(5, window_min=2, review_min=0)
            self.agents_say({"4242": "waiting"})
            shown = []
            log = self.follow_on_a_clock(9, at={0.5: lambda: self.coordinator_task_ended("Add a"), 4: lambda: self.coordinator_task_ended("Add b"),
                                               7: lambda: shown.append(self.hansa_out("status"))})[0]
            alerts = self.coordinator_alerts()
            self.assertEqual(len(alerts), 1, (alerts, log))
            self.assertIn(f"{waits} (a permission dialog or a question) for 2 min, so it cannot act on what hansa "
                          "posted to it: 1 thing(s) since ", alerts[0])
            self.assertIn(", the oldest: t0001 done: Add a (no changes) · answer it in that session", alerts[0])
            self.assertIn(f"{waits} for 6 min (a permission dialog or a question)", shown[0])
            self.assertEqual(len(posted()), 2)
            self.assertTrue(3 <= self.looked_up() <= 9, self.looked_up())  # at most once a minute, from the first post

        def row6():
            """status busy, idle, shell or a word hansa does not know, for as long: none"""
            self.coordinator_desk(6, window_min=2, review_min=0)
            for said in ("busy", "idle", "shell", "thinking"):
                self.agents_say({"4242": said})
                self.follow_on_a_clock(6, at={0.5: lambda: self.coordinator_task_ended(f"Add {said}")})
            self.assertEqual(self.coordinator_alerts(), [])
            self.assertGreaterEqual(self.looked_up(), 4 * 4)  # it looked, and saw no window waiting

        def row7():
            """claude agents --json fails or prints garbage: none, and the follower's log says so"""
            self.coordinator_desk(7, window_min=2, review_min=3)
            logs = []
            for said in ("exit 3", "garbage, not JSON"):
                self.agents_say(said)
                logs.append(self.follow_on_a_clock(6, at={0.5: lambda: self.coordinator_task_ended("Add a")})[0])
            self.assertEqual(self.coordinator_alerts(), [])
            self.assertIn("could not look up the session's status for the principal's coordinator alert: claude agents "
                          "--json ended with 3: the sessions cannot be listed", logs[0])
            self.assertIn("could not look up the session's status for the principal's coordinator alert: claude agents "
                          "--json printed what is not JSON: 'garbage, not JSON'", logs[1])

        def row8():
            """a task waits for review N3 minutes, the session idle at a check after that: one alert for it"""
            self.coordinator_desk(8, window_min=0, review_min=3)
            self.agents_say({"4242": "idle"})
            shown = []
            self.follow_on_a_clock(9, at={0.5: lambda: self.coordinator_task_ended("Add a"),
                                          8: lambda: shown.append(self.hansa_out("status"))})
            self.assertEqual(self.coordinator_alerts(), [
                "the coordinator's session pid 4242 (desk-4242) is idle while t0001 has waited for review for 3 min "
                "since hansa posted it there: Add a · hansa does not post it again"])
            self.assertEqual(len(posted()), 1)  # hansa does not post it again
            self.assertIn("waiting for review while the coordinator's session pid 4242 (desk-4242) is idle: t0001 for 7 "
                          "min", shown[0])

        def row9():
            """the same, the session busy at each check: none until a check finds it idle"""
            self.coordinator_desk(9, window_min=0, review_min=3)
            self.agents_say({"4242": "busy"})
            before = []
            self.follow_on_a_clock(10, at={0.5: lambda: self.coordinator_task_ended("Add a"),
                                           6.9: lambda: before.append(list(self.coordinator_alerts())),
                                           7: lambda: self.agents_say({"4242": "idle"})})
            self.assertEqual(before, [[]])
            self.assertEqual(len(self.coordinator_alerts()), 1)
            self.assertIn("is idle while t0001 has waited for review for 7 min", self.coordinator_alerts()[0])

        def row10():
            """the task merged or closed before N3: none, and nothing looked up for it"""
            self.coordinator_desk(10, window_min=0, review_min=3)
            self.agents_say({"4242": "idle"})
            tids = []

            def done_with():
                self.desk.update(tids[0], state="merged", merged=time.time())
                self.desk.update(tids[1], state="cancelled", error="closed without merging")
            self.follow_on_a_clock(8, at={0.5: lambda: tids.extend([self.coordinator_task_ended("Add a"), self.coordinator_task_ended("Add b")]),
                                          2: done_with})
            self.assertEqual((self.coordinator_alerts(), self.looked_up()), ([], 0))

        def row11():
            """N1, N2 or N3 set to 0 on the page: that case never alerts"""
            self.coordinator_desk(11, no_session_min=0)
            t = time.time()
            alert.unheard_check(self.desk, t)
            self.coordinator_task_ended("Add a")
            alert.unheard_check(self.desk, t + 2 * 86400)
            self.assertNotIn("no session hears from hansa", self.status_at(t + 2 * 86400))
            for off, said in (({"window_min": 0, "review_min": 3}, "waiting"),
                              ({"window_min": 2, "review_min": 0}, "idle")):
                self.assertEqual(self.page_save(lambda s: s["coordinator_alert"].update(off)),
                                 {"ok": True, "problems": []})
                self.agents_say({"4242": said})
                self.follow_on_a_clock(8, at={0.5: lambda: self.coordinator_task_ended(f"Add {said}")})
            self.assertEqual(self.coordinator_alerts(), [])

        def row12():
            """the page saves -1, 1441 or 2.5: refused, saying why"""
            self.coordinator_desk(12)
            self.assertEqual(self.desk.settings()["coordinator_alert"],
                             {"no_session_min": 10, "window_min": 10, "review_min": 120})
            for k in ("no_session_min", "window_min", "review_min"):
                for bad in (-1, 1441, 2.5):
                    said = self.page_save(lambda s: s["coordinator_alert"].update({k: bad}))
                    self.assertFalse(said["ok"], (k, bad))
                    self.assertEqual([x for x in said["problems"] if x.startswith("coordinator_alert: ")], [
                        f"coordinator_alert: {COORDINATOR_ALERT_WHAT[k]} ({k}) must be a whole number from 0 (off) to "
                        f"1440, not {json.dumps(bad)}"])
            edges = {"no_session_min": 0, "window_min": 1440, "review_min": 1}
            self.assertEqual(self.page_save(lambda s: s.update(coordinator_alert=edges)), {"ok": True, "problems": []})
            s = self.desk.settings()
            s["coordinator_alert"] = {"no_session_min": 5, "window_min": 5, "review_min": 5}
            self.assertEqual(self.desk.save_settings(s, by="coordinator"), [
                "coordinator_alert is the principal's, set only on the web page (Settings); ask with hansa ask"])
            self.assertEqual(self.desk.settings()["coordinator_alert"], edges)
            ui = (Path(__file__).resolve().parent.parent / "hansa" / "ui.html").read_text()
            for k in ("no_session_min", "window_min", "review_min"):
                self.assertIn(f'bind(S.coordinator_alert, "{k}", "number")', ui)

        def row13():
            """a follower restarted on new code after a case-2 alert, the stretch still going: no second alert"""
            self.coordinator_desk(13, window_min=2, review_min=0)
            self.agents_say({"4242": "waiting"})
            _, end, carried = self.follow_on_a_clock(9, at={0.5: lambda: self.coordinator_task_ended("Add a")}, restart_at=4)
            self.assertEqual(len(self.coordinator_alerts()), 1)
            self.assertTrue(carried and carried["watch"]["told"], carried)
            log = self.follow_on_a_clock(8, at={1: lambda: self.coordinator_task_ended("Add b"), 4: lambda: self.coordinator_task_ended("Add c")},
                                         start=end, resume=carried)[0]
            self.assertIn("restarted on hansa's new code", log)
            self.assertEqual(len(self.coordinator_alerts()), 1)
            self.assertEqual(len(posted()), 3)

        def row14():
            """an idle round with nothing waiting: no claude agents run (and the idle-round test unchanged)"""
            self.coordinator_desk(14, window_min=2, review_min=3)
            self.agents_say({"4242": "waiting"})
            d = Dispatcher(self.desk)
            d.tick()
            alert.unheard_check(self.desk)
            log = self.follow_on_a_clock(10, at={5: d.tick, 6: lambda: alert.unheard_check(self.desk)})[0]
            d.tick()
            self.assertEqual((self.looked_up(), self.coordinator_alerts()), (0, []), log)

        def row15():
            """a follower starts named, with something waiting and status waiting: no two runs of claude agents --json
            within 60 s, counting the name lookup (also while the Watch's runs fail, so that none names the session)"""
            self.coordinator_desk(15, window_min=1, review_min=0)
            self.agents_say({"4242": "waiting"})
            ran, real = [], notify.agents_rows

            def rows(timeout=15):
                ran.append(notify.time.time())
                return real(timeout)
            with unittest.mock.patch.object(notify, "agents_rows", rows):
                log = self.follow_on_a_clock(8, at={0.1: lambda: self.coordinator_task_ended("Add a"),
                                                     1.5: lambda: self.agents_say("exit 3")}, namer=True)[0]
            gaps = [b - a for a, b in zip(ran, ran[1:])]
            self.assertTrue(ran and min(gaps) >= 60, (ran, log))
            self.assertGreaterEqual(len(ran), 6)  # the Watch looks once a minute, and its runs name the session too
            self.assertEqual(len(self.coordinator_alerts()), 1)

        def row16():
            """a task that records no session waits N3 minutes; two live followers, both sessions idle: one alert in
            all"""
            self.coordinator_desk(16, window_min=0, review_min=3)
            self.agents_say({"4242": "idle", "4343": "idle"})
            log = self.follow_on_a_clock(8, at={0.5: lambda: self.coordinator_task_ended("Add a")}, also=[4343])[0]
            self.assertEqual(len(self.coordinator_alerts()), 1, (self.coordinator_alerts(), log))
            self.assertIn("is idle while t0001 has waited for review for 3 min", self.coordinator_alerts()[0])
            self.assertIn("the principal's coordinator alert (review) went already: another follower alerted of this "
                          "task", log)
            self.assertEqual((len(posted()), len(self.posts(str(self.tmp / "inbox-desk-16-1.sock")))), (1, 1))

        def row17():
            """after a case-1 alert, a follower starts and ends within 5 s, between two looks; then something waits N1
            minutes with none listening: a second alert"""
            from hansa import desk as desk_module
            self.coordinator_desk(17)
            p, _ = self.session()
            sess = {"pid": p.pid, "start": notify.proc_start(p.pid)}
            me = {"key": notify.key_of(sess), "session": sess, "uid": os.getuid(), "name": "desk-87"}
            t = time.time()
            alert.unheard_check(self.desk, t)
            self.coordinator_task_ended("Add a")
            alert.unheard_check(self.desk, t + 11 * 60)
            self.assertEqual(len(self.coordinator_alerts()), 1)
            with unittest.mock.patch.object(notify, "now", lambda: t + 11 * 60 + 2):  # after one look, before the next
                notify.handle(self.desk, {"op": "start", "me": me})
            with unittest.mock.patch.object(notify, "now", lambda: t + 11 * 60 + 6):
                notify.handle(self.desk, {"op": "end", "me": me, "done": notify.log_end(self.desk)})
            p.kill()
            p.wait()
            with unittest.mock.patch.object(desk_module, "now", lambda: t + 12 * 60):
                self.coordinator_task_ended("Add b")
            alert.unheard_check(self.desk, t + 11 * 60 + 10)
            alert.unheard_check(self.desk, t + 21 * 60)
            self.assertEqual(len(self.coordinator_alerts()), 1)
            alert.unheard_check(self.desk, t + 22 * 60)
            self.assertEqual(len(self.coordinator_alerts()), 2)
            self.assertIn("· 1 thing(s) wait for the coordinator, the oldest for 10 min: t0002 done: Add b",
                          self.coordinator_alerts()[1])

        from hansa.desk import COORDINATOR_ALERT_WHAT
        rows = [row1, row2, row3, row4, row5, row6, row7, row8, row9, row10, row11, row12, row13, row14, row15, row16,
                row17]
        for n, row in enumerate(rows, 1):
            with self.subTest(row=n, rule=row.__doc__):
                row()
        self.assertIn("coordinator", alert.KINDS)
        self.assertIn("`coordinator`", self.hansa_out("help", "alerts"))

    # -- small fixes from earlier verifications --

    def page_post(self, path: str, body: dict) -> dict:
        """What the page's server answers to a POST, handled over a socket pair (no port is opened)."""
        from hansa import web
        made = {}

        class Server:
            def __init__(self, address, handler):
                made["handler"], self.server_address = handler, address

            def serve_forever(self):
                pass
        with unittest.mock.patch.object(web.http.server, "ThreadingHTTPServer", Server):
            start_web(self.desk, "127.0.0.1", 0)
        data = json.dumps(body).encode()
        ours, theirs = socket.socketpair()
        with ours, theirs:
            ours.sendall(f"POST {path}?t={self.desk.web_token()} HTTP/1.0\r\nX-Hansa: 1\r\n"
                         f"Content-Length: {len(data)}\r\n\r\n".encode() + data)
            made["handler"](theirs, ("127.0.0.1", 0), None)
            theirs.shutdown(socket.SHUT_WR)
            answer = b""
            while chunk := ours.recv(65536):
                answer += chunk
        return json.loads(answer.split(b"\r\n\r\n", 1)[1])

    def test_show_full_gives_claude_codes_reason_for_a_refused_call_whole(self):
        tid = self.desk.new_task("Build it")
        why = "This command reads outside the folders allowed: " + "x" * 300 + " (the end of the reason)"
        self.desk.update(tid, state="done", denials=["Bash: make"], denial_reasons=[why])
        self.assertIn(f"Claude Code said: {why}", views.show_text(self.desk, tid, full=True))
        self.assertNotIn("(the end of the reason)", views.show_text(self.desk, tid))

    def test_the_page_cannot_answer_a_request_that_was_closed_meanwhile(self):
        self.desk.add_ask("May the docs lane use the npm registry?")
        self.desk.close_ask_as_coordinator(1, "done without it")
        # a page that had not refreshed yet still shows it open
        said = self.page_post("/api/ask/close", {"id": 1, "answer": "Yes"})
        self.assertFalse(said["ok"])
        self.assertEqual(said["problems"], ["request #1 was already closed by the coordinator (done without it); "
                                            "your answer was not taken"])
        a = self.desk.asks()[0]
        self.assertEqual((a["closed_by"], a["reason"], a["answer"]), ("coordinator", "done without it", ""))
        self.assertEqual(len(self.events("ask_closed")), 1)
        self.assertEqual(self.desk.close_ask(1, "again"), "request #1 was already closed by the coordinator "
                                                            "(done without it); your answer was not taken")

    def test_a_merge_check_of_only_spaces_written_by_hand_is_unset(self):
        from hansa import run
        s = json.loads(self.desk.settings_path.read_text())
        s["lanes"]["a"].update(check="true", merge_check="   ")
        self.desk.settings_path.write_text(json.dumps(s))
        ln = self.desk.settings()["lanes"]["a"]
        self.assertNotIn("merge_check", ln)
        self.assertEqual(run.merge_command(ln), "true")
        self.assertFalse(run.own_merge_check(ln))

    def test_lane_add_takes_a_merge_check_and_its_time_limit_and_like_copies_them(self):
        said = self.hansa("lane", "add", "b", "--repo", str(self.repo), "--check", "make test",
                          "--merge-check", "make test-all", "--merge-timeout", "30")
        self.assertIn('merge_check "make test-all"; merge_timeout_min 30', said)
        lanes = self.desk.settings()["lanes"]
        self.assertEqual((lanes["b"]["merge_check"], lanes["b"]["merge_timeout_min"]), ("make test-all", 30))
        self.hansa("lane", "add", "c", "--like", "b")
        self.assertEqual((self.desk.settings()["lanes"]["c"]["merge_check"],
                          self.desk.settings()["lanes"]["c"]["merge_timeout_min"]), ("make test-all", 30))
        self.hansa("lane", "add", "d", "--like", "b", "--merge-check", "none", "--merge-timeout", "none")
        self.assertNotIn("merge_check", self.desk.settings()["lanes"]["d"])
        self.assertNotIn("merge_timeout_min", self.desk.settings()["lanes"]["d"])
        self.hansa("lane", "add", "e", "--repo", str(self.repo), "--merge-check", "  ")
        self.assertNotIn("merge_check", self.desk.settings()["lanes"]["e"])

    def test_a_message_form_written_by_hand_that_hansa_cannot_use_is_said_where_it_falls_back(self):
        s = json.loads(self.desk.settings_path.read_text())
        s["lanes"]["a"].update(commit_message="{title} {when}", merge_message="Merge {task")
        self.desk.settings_path.write_text(json.dumps(s))
        status = views.status_text(views.status(self.desk))
        self.assertIn("WARNING: lane a's commit_message \"{title} {when}\" has an unknown placeholder {when}", status)
        self.assertIn("WARNING: lane a's merge_message \"Merge {task\" has a { or }", status)
        self.assertIn("hansa uses its own message in its place, with the task number (set it right: hansa lane set a "
                      "merge_message ...)", status)
        tid = self.desk.new_task("Add hello.txt")
        m = self.settle(Dispatcher(self.desk), tid)
        self.assertEqual(m["state"], "done", m)
        self.assertEqual(sh_out("git", "log", "-1", "--format=%s", m["head"], cwd=self.repo), f"{tid}: Add hello.txt")
        self.assertIn("message: lane a's commit_message \"{title} {when}\" has an unknown placeholder",
                      views.show_text(self.desk, tid))
        said = self.hansa("merge", tid)
        self.assertIn("note: lane a's merge_message \"Merge {task\" has a { or }", said)
        self.assertEqual(sh_out("git", "log", "-1", "--format=%s", "main", cwd=self.repo), f"Merge {tid}: Add hello.txt")
        self.assertIn("message: lane a's merge_message", views.show_text(self.desk, tid))
        s["lanes"]["a"].pop("commit_message")
        s["lanes"]["a"].pop("merge_message")
        self.desk.settings_path.write_text(json.dumps(s))
        self.assertNotIn("WARNING", views.status_text(views.status(self.desk)))

    def test_verify_of_a_task_whose_lane_was_made_again_on_another_repository(self):
        d, t1, t2 = self.two_lanes()
        self.assertEqual(self.desk.meta(t1)["repo"], str(self.repo.resolve()))  # recorded when it was queued
        s = self.desk.settings()
        other = self.tmp / "other"
        subprocess.run(["git", "clone", "-q", str(self.repo), str(other)], check=True)
        del s["lanes"]["a"]  # removed after t1 ran, then made again by the same name elsewhere
        self.assertEqual(self.desk.save_settings(s), [])
        s["lanes"]["a"] = {**json.loads(json.dumps(s["lanes"]["b"])), "repo": str(other)}
        self.assertEqual(self.desk.save_settings(s), [])
        before = len(self.desk.tasks())
        with self.assertRaises(SystemExit) as e:
            main(["--desk", str(self.desk.root), "verify", t1])
        self.assertEqual(str(e.exception), f"hansa: {t1}'s lane a is now on {other}, not on {self.repo.resolve()}, "
                                           f"where {t1} ran and its branch is (the lane was removed and made again); "
                                           f"verify it with --lane L, a lane on {self.repo.resolve()}; nothing was "
                                           f"queued")
        self.assertEqual(len(self.desk.tasks()), before)
        out = self.hansa("verify", t1, "--lane", "b")  # b is on the repository where t1's branch is
        self.assertIn(f"queued on lane b:", out)

    def test_hansa_serve_writes_the_code_it_runs_as_it_starts(self):
        import errno
        import hansa
        from hansa import web

        def taken(*args):
            raise OSError(errno.EADDRINUSE, "in use")
        held, real = [], cli.hold_server_lock

        def hold(desk):
            held.append(real(desk))
            return held[-1]
        with unittest.mock.patch.object(web, "start_web", taken), unittest.mock.patch.object(
                cli, "hold_server_lock", hold), self.assertRaises(SystemExit):
            main(["--desk", str(self.desk.root), "serve"])
        held[0].close()
        self.assertEqual(json.loads((self.desk.state_dir / "serve-code").read_text()),
                         {"pid": os.getpid(), "build": hansa.build(), "installed": hansa.installed()})

    def test_only_hansas_own_files_count_as_shipped(self):
        import hansa
        here = Path(hansa.__file__).resolve().parent
        own = subprocess.run(["git", "ls-files", "hansa"], cwd=here.parent, capture_output=True, text=True).stdout
        for f in own.split():  # every file the repository has under hansa/
            self.assertTrue(hansa.shipped(Path(f).relative_to("hansa")), f)
        for f in (".DS_Store", "agents/.DS_Store", "run.py~", "__pycache__/run.cpython-312.pyc", "x/y.py",
                  "._cli.py", "._card.md", "agents/._worker.md"):  # macOS's AppleDouble files, left by a copy
            self.assertFalse(hansa.shipped(Path(f)), f)
        for f in ("mod/.claude-plugin/plugin.json", "mod/hooks/hooks.json", "mod/hooks/register.js",
                  "mod/tests/register.test.ts"):  # the coordinator's mod: what its session loads, and its tests
            self.assertTrue(hansa.shipped(Path(f)), f)
        for f in ("mod/.DS_Store", "mod/hooks/.DS_Store", "mod/hooks/register.js~", "mod/hooks/._register.js",
                  "mod/.claude-plugin/._plugin.json", "mod/tests/._register.test.ts", "mod/__pycache__/x.pyc",
                  "mod/x.py", "mod/hooks/x/y.js", "mod/register.js", "x/mod/hooks/register.js",
                  "mod/tsconfig.json", "mod/.claude-plugin/types/index.d.ts",  # what Claude Code writes as it loads it
                  "mod/.claude/.cc-writes/x"):
            self.assertFalse(hansa.shipped(Path(f)), f)

